/** Read-only revalidation before the single provider restart; never writes evidence. */
import { readFile } from 'node:fs/promises';
import { verifyContinuation4Lifecycle } from '../evaluations/research-qa/m78-continuation4-lifecycle-independent-review';
const sha = (s: Uint8Array | string) => new Bun.CryptoHasher('sha256').update(s).digest('hex');
const check: (v: unknown) => asserts v = v => { if (!v) throw new Error('restart admission refused'); };
const [path, expected] = process.argv.slice(2); check(path === 'evaluations/research-qa/m78-continuation4-exercise-actual-qa-result.json');
const qaBytes = await readFile(path); check(sha(qaBytes) === expected);
const qa = JSON.parse(qaBytes.toString('utf8'));
check(qa.status === 'm78_independent_continuation4_exercise_passed' && qa.reviewerId === '/root/m78_transport_probe' && qa.materialFindingsOpen === 0);
check(qa.lifecycleReview?.path === 'evaluations/research-qa/m78-continuation4-lifecycle-qa-identity-binding-repair-result.json' && qa.lifecycleReview.sha256 === '206130bed4adcad7fc6608d9d98fbb3f4c94d92a960abdfb8a995d816e50a7f3');
check(qa.applicationPostRequests === 37 && qa.actualRestartVerified === false);
check(qa.rootEvaluation.path === 'evaluations/research-qa/m78-continuation4-exercise-evaluated-result.json');
const rootBytes = await readFile(qa.rootEvaluation.path); check(sha(rootBytes) === qa.rootEvaluation.sha256);
const root = JSON.parse(rootBytes.toString('utf8'));
check(root.status === 'm78_independent_continuation4_exercise_passed' && root.executionOwner === '/root' && root.applicationPostRequests === 37 && root.actualRestartVerified === false);
check(root.exerciseGate.path === '.superpowers/m78-continuation4-exercise-gate.json');
const gateBytes = await readFile(root.exerciseGate.path); check(sha(gateBytes) === root.exerciseGate.sha256);
const gate = JSON.parse(gateBytes.toString('utf8'));
check(gate.mode === 'exercise' && gate.profile === 'm78-root-continuation4-journey-gate-v1');
check(gate.artifacts.lifecycleReview.sha256 === '206130bed4adcad7fc6608d9d98fbb3f4c94d92a960abdfb8a995d816e50a7f3');
check(root.evaluator.sha256 === '8b93064892ff12647f2cb08055a6840172358d23a5c0a028ca0ce1bfb793ad18');
for (const pin of Object.values(gate.artifacts) as Array<{path:string;sha256:string}>) check(sha(await readFile(pin.path)) === pin.sha256);
check(gate.sourcePins.length === 173);
for (const pin of gate.sourcePins) check(sha(await readFile(pin.path)) === pin.sha256);
check(root.journalPath === '.superpowers/m78-hosted-continuation4.jsonl' && root.diagnosticPath === '.superpowers/m78-hosted-continuation4-diagnostics.jsonl');
const journal = await readFile(root.journalPath, 'utf8'), diagnostics = await readFile(root.diagnosticPath, 'utf8');
check(sha(journal) === root.admission.journalSha256 && sha(diagnostics) === root.admission.diagnosticsSha256);
const actual = await verifyContinuation4Lifecycle(journal, diagnostics, root.admission, p => readFile(p, 'utf8'));
check(actual.status === 'm78_independent_continuation4_exercise_passed' && actual.applicationPostRequests === 37 && actual.actualRestartVerified === false);
for (const [key, value] of Object.entries(actual)) check(root[key] === value);
console.log(JSON.stringify({status:'restart_exercise_admission_verified',journalSha256:sha(journal),diagnosticsSha256:sha(diagnostics),rootEvaluation:qa.rootEvaluation}));

